<?php

namespace App\Models;

use Database\Factories\ProductTemplateFactory;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * Sanitized SVG template of a product (PRD-020, design Decision 18): the general one
 * (`variant_value_id` null) or the one for a gender-use value (DEC-PRD-49). `layers` is the sorted
 * list of `<g id>` found in the stored, sanitized file. `variant_key` is generated by the database.
 *
 * @property int $id
 * @property int $product_id
 * @property int|null $variant_value_id
 * @property-read int $variant_key
 * @property string $svg_path
 * @property string $original_name
 * @property list<string> $layers
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 * @property-read Product $product
 * @property-read AttributeValue|null $variantValue
 */
#[Fillable(['product_id', 'variant_value_id', 'svg_path', 'original_name', 'layers'])]
class ProductTemplate extends Model
{
    /** @use HasFactory<ProductTemplateFactory> */
    use HasFactory;

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'product_id' => 'integer',
            'variant_value_id' => 'integer',
            'variant_key' => 'integer',
            'layers' => 'array',
        ];
    }

    /**
     * @return BelongsTo<Product, $this>
     */
    public function product(): BelongsTo
    {
        return $this->belongsTo(Product::class);
    }

    /**
     * @return BelongsTo<AttributeValue, $this>
     */
    public function variantValue(): BelongsTo
    {
        return $this->belongsTo(AttributeValue::class, 'variant_value_id');
    }
}
